<?php $versions = (array) ($studentVersions ?? []); ?>
<section class="sw-card"><header class="sw-section-heading"><div><h2>Versiones</h2><p>Historial disponible de reemplazos documentales.</p></div></header><?php if (!$versions): ?><p class="sw-empty-state">Aún no existen versiones anteriores.</p><?php else: ?><div class="sw-record-list"><?php foreach ($versions as $version): ?><article class="sw-record"><div><strong><?= e((string)($version['original_name'] ?? 'Archivo')) ?></strong><span>Versión <?= (int)($version['version_number'] ?? 0) ?></span></div><small><?= e($formatDate((string)($version['replaced_at'] ?? ''), true)) ?><?= !empty($version['replacement_reason']) ? ' · ' . e((string)$version['replacement_reason']) : '' ?></small></article><?php endforeach; ?></div><?php endif; ?></section>
